import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  
  const basePrice = parseFloat(input?.standard_pricing?.price ?? 0);

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Cargo fijo not found"
      }
    }
  }

 if (basePrice != null) {
    const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);
    billingItem.billing_item_amount = basePrice;

    return {
      ...input,
      result: {
          total_amount: basePrice,
          status: "OK",
          status_description: "Cargo fijo calculation rule completed"
        }
    };
  } else {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "The amount of the Cargo fijo rule could not be calculated."
      }
    };
  }
};
